head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > M > enableAllDate]<br/>Calendar 컴포넌트의 날짜 범위 비활성화 설정을 초기화하여 모든 날짜를 선택 가능한 상태로 활성화합니다.",
    "validation" : [
        "enableAllDate() 메소드를 호출하면 setDisableBeforeDate() 메소드로 설정한 날짜 범위 비활성화가 초기화되어 해당 범위 날짜가 다시 활성화됩니다.",
        "enableAllDate() 메소드를 호출하면 setDisableAfterDate() 메소드로 설정한 날짜 범위 비활성화가 초기화되어 해당 범위 날짜가 다시 활성화됩니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // comp 생성 함수 호출 (초기값은 오늘 날짜 기준으로 자동 설정됨)
    await $c.gcm.createBasicCalendar();
}



// setDisableBeforeDate 실행 — 2025-11-10 이전 날짜를 비활성화
scwin.btn_setDisableBeforeDate_onclick = function (e) {
    target1.setDisableBeforeDate("20251110");
};



// setDisableAfterDate 실행 — 2025-11-25 이후 날짜를 비활성화
scwin.btn_setDisableAfterDate_onclick = function (e) {
    target1.setDisableAfterDate("20251125");
};



// 대상 메소드: enableAllDate 실행
scwin.btn_enableAllDate_onclick = function (e) {
    target1.enableAllDate();
};



// 비활성화 날짜 셀 갯수 / 목록 조회
scwin.btn_getDisabledDates_onclick = function (e) {
    // 현재 표시된 달력 그리드에서 비활성화 처리된 날짜 셀 추출
    const disabledTds = target1.render.querySelectorAll('td.w2calendar_date_disable');

    let disabledDates = [];
    disabledTds.forEach(td => {
        disabledDates.push(td.textContent);
    });

    wf_body_bottom.getObj("scwin").setReturnValue("[비활성화된 날짜 셀 갯수] " + disabledTds.length);
    wf_body_bottom.getObj("scwin").setReturnValue("[비활성화된 날짜 목록] " + disabledDates.join(","));
    wf_body_bottom.getObj("scwin").setReturnValue("[options.disableBeforeDate] " + target1.options.disableBeforeDate);
    wf_body_bottom.getObj("scwin").setReturnValue("[options.disableAfterDate] " + target1.options.disableAfterDate);
};
